#pragma once

#include <cstdint>

namespace bios
{
/**
 * Linear scaling value = raw * num / den + offset, limited to [0, UINT32_MAX].
 * Parameters are generated by tools/bswgen from board.yaml (analogInputScaleConfiguration.h).
 * Rounds down like bios::scaleFunction.
 */
template<uint32_t num, uint32_t den, int32_t offset>
uint32_t scaleLinear(uint16_t const raw)
{
    static_assert(den != 0U, "scaleLinear: den must not be 0");
    int64_t const value
        = static_cast<int64_t>((static_cast<uint64_t>(num) * raw) / den) + static_cast<int64_t>(offset);
    if (value < 0)
    {
        return 0U;
    }
    if (value > static_cast<int64_t>(UINT32_MAX))
    {
        return UINT32_MAX;
    }
    return static_cast<uint32_t>(value);
}

} // namespace bios
